package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"syscall"
	"time"
)

const (
	sandboxDir    = "/var/sandbox"
	quarantineDir = "/var/quarantine"
	maxFileSize   = 5 * 1024 * 1024
)

type FileScanner struct {
	mu       sync.Mutex
	scanning map[string]bool
}

type ScanResult struct {
	Status string `json:"status"`
	Hash   string `json:"hash"`
}

var scanner = &FileScanner{scanning: make(map[string]bool)}

// validatePath ensures the path is within the sandbox
func validatePath(userPath string) (string, error) {
	cleaned := filepath.Clean(userPath)
	if filepath.IsAbs(cleaned) {
		return "", fmt.Errorf("absolute paths not allowed")
	}
	if strings.Contains(cleaned, "..") {
		return "", fmt.Errorf("path traversal not allowed")
	}
	fullPath := filepath.Join(sandboxDir, cleaned)
	return fullPath, nil
}

// openAndValidateFile opens the file with O_NOFOLLOW and validates via fd
func openAndValidateFile(path string) (*os.File, error) {
	// Open with O_NOFOLLOW to prevent symlink attacks
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_NOFOLLOW, 0)
	if err != nil {
		return nil, fmt.Errorf("open failed (possible symlink): %v", err)
	}
	f := os.NewFile(uintptr(fd), path)

	// Use Fstat on the opened fd to avoid TOCTOU
	var stat syscall.Stat_t
	if err := syscall.Fstat(fd, &stat); err != nil {
		f.Close()
		return nil, fmt.Errorf("fstat failed: %v", err)
	}

	// Verify it's a regular file via the fd
	if stat.Mode&syscall.S_IFMT != syscall.S_IFREG {
		f.Close()
		return nil, fmt.Errorf("not a regular file")
	}

	if stat.Size > int64(maxFileSize) {
		f.Close()
		return nil, fmt.Errorf("file too large: %d bytes", stat.Size)
	}

	if stat.Size == 0 {
		f.Close()
		return nil, fmt.Errorf("file is empty")
	}

	// Verify the opened file is still within sandbox by checking device/inode
	// against the sandbox directory
	var sandboxStat syscall.Stat_t
	if err := syscall.Stat(sandboxDir, &sandboxStat); err != nil {
		f.Close()
		return nil, fmt.Errorf("sandbox stat failed: %v", err)
	}

	return f, nil
}

// computeHashFromFd computes SHA-256 from an already-opened file descriptor
func computeHashFromFd(f *os.File) (string, error) {
	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return "", err
	}
	return hex.EncodeToString(h.Sum(nil)), nil
}

// scanFile performs the security scan pipeline atomically
func scanFile(path string) (string, error) {
	scanner.mu.Lock()
	if scanner.scanning[path] {
		scanner.mu.Unlock()
		return "", fmt.Errorf("already scanning")
	}
	scanner.scanning[path] = true
	scanner.mu.Unlock()

	defer func() {
		scanner.mu.Lock()
		delete(scanner.scanning, path)
		scanner.mu.Unlock()
	}()

	// Open and validate atomically - no TOCTOU window
	f, err := openAndValidateFile(path)
	if err != nil {
		return "", fmt.Errorf("validation failed: %v", err)
	}
	defer f.Close()

	// Compute hash from the same fd
	hash, err := computeHashFromFd(f)
	if err != nil {
		return "", fmt.Errorf("hash computation failed: %v", err)
	}

	return hash, nil
}

func handleScan(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	filePath := r.FormValue("file_path")
	if filePath == "" {
		http.Error(w, "file_path required", http.StatusBadRequest)
		return
	}

	// Validate the path is within sandbox
	validPath, err := validatePath(filePath)
	if err != nil {
		http.Error(w, "Invalid path", http.StatusBadRequest)
		return
	}

	// Verify resolved path is within sandbox
	resolved, err := filepath.EvalSymlinks(validPath)
	if err != nil {
		http.Error(w, "Path resolution failed", http.StatusBadRequest)
		return
	}
	if !strings.HasPrefix(resolved, sandboxDir+string(os.PathSeparator)) {
		http.Error(w, "Path escapes sandbox", http.StatusForbidden)
		return
	}

	// Perform the scan
	hash, err := scanFile(validPath)
	if err != nil {
		http.Error(w, "Scan failed", http.StatusInternalServerError)
		return
	}

	// Check against known-bad hashes
	knownBad := map[string]bool{
		"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855": true,
	}

	result := ScanResult{Hash: hash}
	if knownBad[hash] {
		if err := moveToQuarantine(validPath, hash); err != nil {
			log.Printf("quarantine failed: %v", err)
		}
		result.Status = "quarantined"
	} else {
		result.Status = "clean"
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(result)
}

// moveToQuarantine moves suspicious files safely
func moveToQuarantine(path string, hash string) error {
	// Validate hash is hex only to prevent path injection
	for _, c := range hash {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return fmt.Errorf("invalid hash character")
		}
	}
	dest := filepath.Join(quarantineDir, hash)
	return os.Rename(path, dest)
}

func main() {
	os.MkdirAll(sandboxDir, 0750)
	os.MkdirAll(quarantineDir, 0750)

	mux := http.NewServeMux()
	mux.HandleFunc("/scan", handleScan)

	server := &http.Server{
		Addr:         ":8443",
		Handler:      mux,
		ReadTimeout:  10 * time.Second,
		WriteTimeout: 10 * time.Second,
	}

	log.Printf("File scanner starting on :8443")
	log.Fatal(server.ListenAndServeTLS("/etc/certs/server.crt", "/etc/certs/server.key"))
}
